const defaults = {length: 'normal', min: 800, max: 1400, style: 'daily', custom: '', thoughtSummary: false};
const lengths = {short: [400, 700], normal: [800, 1400], long: [1600, 2400]};
const styles = {
  daily: ['现代日常', '用具体生活细节、自然口语对白与轻微幽默组织日常。关系从共同做事和即时回应中显露；保留人物差异、冲突和失落，不强行温情或治愈。'],
  novel: ['轻小说群像', '以清楚的动作、鲜明对白与人物反应形成节奏，可有符合人物口吻的自然吐槽；不堆砌夸张比喻，不把所有人写成同一种声音。'],
  plain: ['克制白描', '以准确、简洁的动作、对白及可观察细节推进场景，少作解释与评价，让具体变化和停顿承担表达。'],
  lyrical: ['细腻抒情', '通过环境、声音、动作节奏和留白呈现细腻氛围，语言清楚节制，不把普通小事强写成宏大情绪。'],
  mystery: ['悬疑写实', '重视可观察线索、行动因果与人物信息差，细节有依据，疑点来自已有事实；不为营造气氛硬造危险或暗中改写设定。'],
  custom: ['自定义文风', ''],
};
const thoughtTags = 'think|thinking|reasoning|analysis|ECoT|cot|draft|draft_notes|acg_think|lore_search|combat_driver|story_driver|dice_calculation|parallel_line_drive';
const noiseRules = [
  {key:'thought-blocks', label:'思考与草稿块', pattern:'<('+thoughtTags+')\\b[^>]*>[\\s\\S]*?(?:<\\/\\1\\s*>|$)', flags:'gi', replacement:'', raw:true},
  {key:'thought-fences', label:'思考与草稿代码块', pattern:'```(?:thinking|think|reasoning|analysis|cot|draft)\\b[^\\n]*\\r?\\n[\\s\\S]*?(?:```|$)', flags:'gi', replacement:'', raw:true},
  {key:'thought-heading', label:'思考过程前缀', pattern:'^\\s*(?:思考过程|推理过程|内部分析|analysis|thinking|reasoning)\\s*[:：][\\s\\S]*?(?=<content\\b|$)', flags:'i', replacement:'', raw:true},
  {key:'thought-closers', label:'残留思考闭合标签', pattern:'<\\/(?:'+thoughtTags+')\\s*>', flags:'gi', replacement:'', raw:true},
  {key:'transport-tail', label:'异常工具协议尾缀', pattern:'(<\\/(?:content|time)\\s*>\\s*)(?:```[^\\r\\n]*\\r?\\n)?(?:call\\s*:\\s*default_api\\s*:\\s*antitrunc_reply\\b|<\\|(?:im_end|eot_id|endoftext)\\|>|\\[DONE\\])[^]*$', flags:'gi', replacement:'$1', raw:true},
  {key:'partial-tag', label:'流式未完成标签', pattern:'<(?:[A-Za-z_/][^>\\r\\n]*)?$', flags:'g', replacement:'', raw:false},
];
function cleanOutput(raw, delimiters) {
  let text = String(raw ?? '').replace(/<xzs_plan\b[^>]*>[\s\S]*?(?:<\/xzs_plan\s*>|$)/gi, '').replace(/<xzs_summary\b[^>]*>[\s\S]*?(?:<\/xzs_summary\s*>|$)/gi, '');
  if (delimiters?.prefix && delimiters?.suffix) {
    const escape = value => String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    text = text.replace(new RegExp(escape(delimiters.prefix)+'[\\s\\S]*?(?:'+escape(delimiters.suffix)+'|$)','g'), '');
  }
  for (const rule of noiseRules) text = text.replace(new RegExp(rule.pattern, rule.flags), rule.replacement);
  return text;
}
function normalizeConfig(value) {
  const c = {...defaults, ...value};
  if (!Object.hasOwn(lengths, c.length) && c.length !== 'custom') throw Error('请选择有效的字数档位。');
  if (!Object.hasOwn(styles, c.style)) throw Error('请选择有效的文风。');
  if (c.length !== 'custom') [c.min, c.max] = lengths[c.length];
  c.min = Number(c.min); c.max = Number(c.max);
  if (!Number.isInteger(c.min) || !Number.isInteger(c.max) || c.min < 100 || c.max > 10000 || c.min > c.max) throw Error('自定义字数须为100—10000之间的整数，且下限不高于上限。');
  c.thoughtSummary = c.thoughtSummary === true || c.thoughtSummary === 'true';
  c.custom = String(c.custom ?? '').trim();
  if (c.style === 'custom' && !c.custom) throw Error('选择自定义文风时，请填写文风内容。');
  return c;
}
function writingPrompt(value) {
  const c = normalizeConfig(value);
  return '<xzs_writing_config>\n正文目标：' + c.min + '—' + c.max + '个可见字符，优先写到区间中段约' + Math.round((c.min+c.max)/2) + '字。只计叙述与对白；空白、标签、思考、时间戳、协议标记和媒体控件不计。中文、标点、字母及数字各计一个字符。收束前核对正文篇幅：低于' + c.min + '字时补足当前互动的具体动作、对白与可观察细节，不把约数当作可以提前结束的理由。字数是写作目标，不通过截断补齐；扩写当前互动，不为了篇幅替玩家决定或增加事件、镜头和经过时间。\n当前文风：' + styles[c.style][0] + '。\n' + (c.style === 'custom' ? c.custom : styles[c.style][1]) + '\n文风只控制语言、句式、节奏和描写密度，仍遵守人物、时间、知识边界、玩家控制及输出协议。\n' + (c.thoughtSummary ? "可见创作规划与约束核对开启：回复最开头只用一组<xzs_plan>…</xzs_plan>，按四类核对槽位的顺序组织本轮小项；闭合后再输出正文与时间字段。唯一固定小项是1.2“时间变化与最近节点”，每轮剧情回复都输出。其余分类和编号小项是可选核对池，不固定出单，不强制每部分输出至少三个小项，也不强制补齐四部分；只展开本轮真正影响正文的事实、选择、冲突、限制或安排，整类没有相关内容时连标题一起省略，已采用的小项保持所属分类和编号顺序。\n不设置规划的独立总字数上限，不将规划挤进正文字数目标，也不将相关内容压成一段概述。相关项充分展开，不相关项直接省略；原文出现在上下文里不等于每轮必须复述，不输出“无误、正常、略过、位置未变化、没有此类事件”等占位说明。输出用户可读的创作方案与约束执行结论，不展示隐藏内部推理、逐步演算或正文草稿。\n【规划对正文生效】已输出的相关分项是紧接着的本轮正文要执行的方案，不是场外感想或独立小正文。每项明确本轮已确认的依据、采用的处理结论或执行边界；正文必须逐项落实本轮选定的角色身份与称呼、知识边界、衣着/现场状态、动作范围、文风篇幅、互动重点及收束位置。实际适用的禁词、防八股文、物理限制和输出封装核对放在最后，并作用于正文；不相关项虽省略显示，原文规定本身的既有适用范围不因此缩小。\n规划只确定有当前事实和适用原文支持、本轮能够执行的安排。未确认的信息写明未确认，并采用不依赖该未知信息的承接；不能在正文补造事实、改变原设定或替玩家作决定来兑现规划。不把准备采用的安排写成已经发生的事件或进度，不借规划新增人物知识、关系、许可或解锁。正文生成时保持与规划一致，不输出一份计划后另写不受其约束的内容。\n依据限于本轮实际载入的世界书原文、角色资料、当前有效聊天及预设选项。时间段、作息、学籍、任职、人数、开放许可等具体制度结论，须对照本轮已载入的对应条目后确认；在相关小项标明采用的原条目名称及本轮结论，不能用一般生活印象替代原文，不能将相邻时段或不同身份的规定混用。以下槽位只组织核对与执行顺序，不改写、删减、扩写或替代原文限制，不另造同类规则；其他已载入且本轮适用的限制依原条目名称归入对应部分，冲突按已有优先规则处理。规划中提到格式时只用“正文块”“时间字段”等中文名称，不抄写尖括号标签、示例时间串、scene字段或可执行的媒体/事件/进度标记。\n" : '可见创作规划与约束核对关闭：直接输出正文，不添加<xzs_plan>或规划核对文字。\n') + '</xzs_writing_config>';
}
function bodyText(raw) {
  let text = cleanOutput(raw);
  const blocks = [...text.matchAll(/<content\b[^>]*>([\s\S]*?)(?:<\/content\s*>|$)/gi)];
  if (!blocks.length) return null;
  text = blocks.map(m => m[1]).join('\n');
  return text.replace(/<(time|bbs_start|bbs_end|audio|video|script|style|iframe)\b[^>]*>[\s\S]*?(?:<\/\1\s*>|$)/gi, '')
    .replace(/^\s*[\[【](?:场景事件|剧情触发|世界事件|奉心祭)[\]】].*$/gm, '')
    .replace(/<!--[^]*?(?:-->|$)/g, '')
    .replace(/【(?:歌曲|演奏|演出|点歌|照片|场景|场景事件|事件|主线|剧情|XZS)[^】]*】/g, '')
    .replace(/\[\[(?:XZS|SCENE|STORY)[^\]]*\]\]/gi, '')
    .replace(/<[^>]*>/g, '')
    .replace(/!\[[^\]]*\]\([^)]*\)/g, '').replace(/\[([^\]]*)\]\([^)]*\)/g, '$1').replace(/\*\*|__|~~|`/g, '')
    .replace(/&(?:amp|lt|gt|quot|apos|nbsp|#\d+|#x[\da-f]+);/gi, entity => {
      const named = {'&amp;':'&','&lt;':'<','&gt;':'>','&quot;':'"','&apos;':"'",'&nbsp;':' '}[entity.toLowerCase()];
      if (named !== undefined) return named;
      const hex = /^&#x/i.test(entity), point = parseInt(entity.slice(hex ? 3 : 2), hex ? 16 : 10);
      return point <= 0x10ffff ? String.fromCodePoint(point) : '\ufffd';
    })
    .replace(/[\s\u200b\ufeff]/g, '');
}
function bodyCount(raw) { const text = bodyText(raw); return text === null ? null : [...text].length; }

const planSections = [{"title":"Ⅰ·当前剧情与本轮任务","text":"【第一部分：当前剧情与本轮任务】\n1.2是唯一固定项，其余为候选小项，只输出本轮实际相关的项目：\n1.1 输入与任务：确认玩家这次明确说了什么、做了什么或提出了什么要求，本轮要承接的具体对象与互动重点；不把未作出的选择补成玩家行为。\n1.2 时间变化与最近节点（固定）：沿用当前有效分支的时钟，列明本轮起始时刻、实际准备发生的动作及各自合理耗时、并行/先后关系、合计经过时间和预计结束时刻。普通续写每轮实际经过时间最多15分钟，可以更短；短动作按现有时间字段精度处理，不为每轮固定加同样分钟数；明确已结算的等待/快进只计算一次，多焦点同时发生不重复累计。玩家明确陈述已经到达，或明确要求直接写至抵达时，可以依其已确认输入采用对应跳转；仅给出起终点、说要去、准备前往、正常乘车请求或工具动画都不是已到达确认，不能把长行程一轮写完。对照已载入校历、学校作息、约定、场所开放时间和已确认班次等，选出与本轮身份、地点、活动真正有关的最近一个后续节点，写出节点时刻、剩余时间及本轮是否触及；标明相关原条目或工具结果来源，不将日常印象、相邻时段或他人无关日程当作本轮限制。若动作预计跨过节点，须明确怎样拆段、在节点处表现铃声/约定/班次等变化，或把尚未进行的活动留后，不能仍当作课间或同一条件下无限继续；正文实际经过时间、节点表现和末尾时间字段必须对应这个安排。玩家明确选择继续、缺课、取消约定或改变行程时保留其选择，并按原文和现场反映节点及后续变化，不强制抹回预定结局。尚无可靠起始时刻或后续节点时说明具体缺口，遵守原有首次时间初始化与已知事实边界，不编造班表或约定来填项。仅核对本轮已发生时间，不把未执行计划的总耗时提前结算。\n1.3 当前剧情与位置锚点：依据当前有效分支与已载入资料，确认玩家实际地点、在场者及已发生/尚未完成事项，区分眼前、回忆与未来安排；相关地点发生移动时再联用3.4，不为静态位置列出通勤项。\n1.4 本轮动作范围：明确这次正文能够推进的互动、仍待玩家回应的位置及不越过的行为边界；按已投放剧情的原文处理前置和阶段，不为完成计划改写前置。\n1.5 文风、篇幅与收束：本轮有具体表达安排或相关风险时，明确当前预设选定的文风、正文目标字数、有效人称/视角，以及具体推进到哪次回应或哪个动作即停；不为列出默认选项而重复已有说明。已采用的选择直接约束紧接着的正文。"},{"title":"Ⅱ·人物、身份与知识边界","text":"【第二部分：人物、身份与知识边界】\n以下为候选小项，只输出本轮实际相关的项目：\n2.1 身份与关系：核对实际参与者的档案、当前身份、已有关系和称呼参照，列明与本轮行为相关的职务/学籍/权限/居住边界；未载入的身份细节不作确定判断。\n2.2 防全知与事实来源：依据已载入原文，明确相关人物各自可知信息、信息来源与尚不知道的关键内容，确定正文能够透露和不能透露的信息；读者/模型知道的内容不直接变成角色知识。\n2.3 人设与声口：依据角色档案、角色扮演限制器、人际社交及去职业病等适用原文，确定本轮角色采用的说话方式、可观察反应与相处尺度；正文按这些结论演绎，不只列性格标签。\n2.4 外貌、衣着与描写：实际涉及相应描述时，按独立人物档案、既定外貌优先、面部库适用范围、衣物描写及其他适用描述约束原文，确认本轮可写的细节与遮挡状态；正文保持同一状态与原文边界。"},{"title":"Ⅲ·场景与专门约束","text":"【第三部分：场景与专门约束】\n以下为候选小项，只输出本轮实际相关的项目，不为覆盖分类添人、添事或编造特殊场景：\n3.1 场所与互动条件：按已载入地点/机构/家庭资料，确认当前互动的空间条件、开放时段、现场许可及可用物品；路线或设施未载入时，明确正文采用的不依赖未知资料的承接方式。\n3.2 日常与群像安排：按当前实际在场者和适用原文，确定本轮谁参与什么互动、怎样承接现场生活细节；饮食、经济、卫生、疲惫、季节衣着和多人调度实际涉及才采用对应原文，不为满足小项添人添事。\n3.3 剧情阶段与结果边界：有已投放主线/场景时按其原文确定本轮可发生阶段、真实前置与未满足项；没有相关事件时，明确这次日常互动推进到哪里、哪些关系或状态仍不成立。正文不能越过这些边界或把计划直接当作完成记录。\n3.4 位置转移与通勤：仅在本轮实际涉及玩家出行计划、已选择的移动或承接正在进行的通勤时展开；静态位置、只提到地名或他人出行不触发，不输出“位置未变化”占位。依已载入的“本轮地理·确认地图”、导航目标、真实通勤轨迹、电车行程及对应场所资料，说明本轮相关的起点、目的地/具体落点、交通工具、路线与必要换乘/接驳、预计耗时及其来源、已实际经过时间和本轮停在何阶段；与1.2的可用时间和最近节点对照，超过可用窗口时不能默写成顺利完成。普通长途每轮最多实际经过15分钟，只写本轮已经走到的路段，后续轮次承接有效分支的进度，不重走起点、不重复计时；累计真实过程完成后自然抵达，只有玩家明确已到或明确要求直接写至抵达才可跳过尚未写出的长过程。短途可在一轮完成，但仍须依现有地图交代离开原处、经过实际道路/连廊/楼梯及中间设施、进入目标的过程；教学楼到旧校舍等校内移动不能只写“已经到了”，也不编造未经过的设施。已有班次与行程计算结果原样作为依据，不按示意坐标编分钟或擅造直达线；没有可靠资料时保留未确认项，不为出行凑精确数字。正文落实本轮确实选择并发生的路段，明确是出发、途中、到站还是进入具体场所；末尾时间字段只记录实际经过时间，地点字段只写本轮结束的真实当前位置，使用已确认地图名称和必要的校内建筑/楼层/房间细节，供原有地图、校内导航与通勤工具按当前分支回读。预计行程不是已完成轨迹，尚未抵达的目的地不写成当前位置，到站不等于进入邻近建筑；规划本身不直接触发定位或计时。\n3.5 音乐与媒体：实际演唱、演奏、合唱、圣咏或共同聆听时，按已载入曲目、演出者、编制、现场条件、录音版本及媒体规则原文确定安排；符合条件的完整标记只放入对应正文现场。\n3.6 亲密场景适用限制：仅在本轮确实涉及时，核对已载入世界书中的适用限制条目，写条目名称与本轮执行结论；原文保持不变，不删改、不扩写、不另造替代规则，不在规划中抄写露骨细节。\n3.7 其他专门约束：其他已载入且本轮适用的规则依原条目作用范围补充，结论同样约束正文；未触发项不列空项。"},{"title":"Ⅳ·禁词、文句与物理终检","text":"【第四部分：禁词、文句与物理终检】\n以下为候选小项，仅以本轮实际相关、紧接着正文将采用的执行结论收尾，不重背规则或列“无误”：\n4.1 禁词表：依据已载入《禁词表》的原文及适用范围，指出与本轮实际表达相关的用词约束和正文采用的处理方式，不另造禁词。\n4.2 防八股文：依据已载入的禁词表、角色扮演规范、角色扮演限制器及去职业病等原文，确定本轮应避免的对应模板化写法、上文重复动作或句式，以及正文实际采用的表达安排；分组名称不冒充世界书中另有同名条目，不新增同类禁令。\n4.3 物理限制：依已载入世界基石、地理导航、衣物遮挡、现场动作条件及人物能力原文核对本轮动作的空间、时序、遮挡与可执行范围，保留原有能力例外；正文保持这些事实，不另加现实设定覆盖原文。\n4.4 输出封装与一致性：按原预设、小手机分工及实际适用媒体/剧情协议，确定正文边界、时间地点、实际所需标记与正文字数目标；紧接着的正文须落实前面三部分的本轮选择，规划与正文分离，不能让格式或状态记录把规划当成已完成事件。"}];
function planSectionPrompt(index,value) { const c=normalizeConfig(value);return '<xzs_plan_section id="'+index+'">\n'+(c.thoughtSummary?planSections[index-1].text:'本轮创作规划关闭，不输出本部分。')+'\n</xzs_plan_section>'; }

